-- =============================================================================
--  VIJAY VARGIYA GROUP OF HOSPITALS - seed data (generated by app.tools.export_seed)
--  Roles, permissions, demo staff logins, specialties, medicines and holidays.
--  Apply with:
--    mysql -u root -p vijay_vargiya_hospital < sql/03_seed.sql
--  NOTE: patient/doctor demo history is generated by `python -m app.seed` so the
--        slot engine and billing maths stay consistent.
-- =============================================================================
SET NAMES utf8mb4;
USE `vijay_vargiya_hospital`;

