-- holidays ---
INSERT INTO holidays (name, holiday_date, is_full_day, created_at, updated_at)
  SELECT 'Republic Day', CONCAT(YEAR(CURDATE()), '-01-26'), 1, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM holidays h WHERE h.holiday_date = CONCAT(YEAR(CURDATE()), '-01-26'));
INSERT INTO holidays (name, holiday_date, is_full_day, created_at, updated_at)
  SELECT 'Holi', CONCAT(YEAR(CURDATE()), '-03-04'), 1, NOW(), NOW()
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM holidays h WHERE h.holiday_date = CONCAT(YEAR(CURDATE()), '-03-04'));
